"""Regression coverage for declaration preparation in Maybe deciders."""

import pytest

import factory


@pytest.mark.parametrize('choice', [0, 1])
def test_faker_decider_defaults(choice):
    class ExampleFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Faker('random_int', min=choice, max=choice, locale='fr_FR'),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory.create_batch(3) == [
        {'value': 'yes' if choice else 'no'}
    ] * 3


@pytest.mark.parametrize('choice', [0, 1])
def test_faker_decider_unrolls_defaults(choice):
    class ExampleFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Faker(
                'random_int',
                min=factory.LazyFunction(lambda: choice),
                max=factory.LazyFunction(lambda: choice),
            ),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory()['value'] == ('yes' if choice else 'no')


def test_nested_maybe_decider():
    class ExampleFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Maybe(factory.LazyFunction(lambda: True), True, False),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory()['value'] == 'yes'
EOF
pytest --no-header -rA --tb=line --color=no -p no:cacheprovider -W ignore::DeprecationWarning tests/test_regression.py

